    "ent=data.message||'비밀번호 불일치';err.style.display='block';}else alert(data.message||'비밀번호 불일치');}}  ).catch(function(e){if(err){err.textContent='오류: '+uiErrorText(e);err.style.display='block';}else alert('통신 오류: '+uiErrorText(e));})  .finally(function(){if(btn){btn.classList.remove('btn-loading');btn.innerHTML='로그인';btn.dataset.authBusy='false';btn.disabled=false;refreshAuthFailures();renderAuthFailures();}});}function loadAdminSettings(){  sdRefresh();fetch('/api/settings').then(function(r){return r.json();})  .then(function(data){if(data&&typeof data.init_view!=='undefined'){var rs=document.getElementsByName('initViewOpt');for(var i=0;i<rs.length;i++){if(parseInt(rs[i].value)===data.init_view)rs[i].checked=true;}var p=document.getElementById('initPagePath');if(p)p.value=data.init_page||'';}})  .catch(function(e){console.error(e);});}function saveInitViewSetting(){  if(!g_adminPw&&!g_adminSession){alert('먼저 인증하세요.');return;}  var btn=document.getElementById('btnSaveInitView'),oh=btn?btn.innerHTML:'';  if(btn){btn.disabled=true;btn.classList.add('btn-loading');btn.innerHTML='<span class=\"spin\"></span> 저장 중...';}  var rs=document.getElementsByName('initViewOpt'),sel='0';  for(var i=0;i<rs.length;i++){if(rs[i].checked){sel=rs[i].value;break;}}  var page=document.getElementById('initPagePath'),pagePath=page?page.value.trim():'';  fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'cur_pw='+encodeURIComponent(g_adminPw)+'&init_view='+encodeURIComponent(sel)+'&init_page='+encodeURIComponent(pagePath)})  .then(function(r){return r.json();})  .then(function(d){if(d.status==='ok')alert('저장 완료. 새 설정은 IPv4/IPv6 루트 주소에 적용됩니다.');else alert('저장 실패: '+(d.message||'오류'));}  ).catch(function(e){alert('통신 오류: '+e);})  .finally(function(){"
    "if(btn){btn.disabled=false;btn.classList.remove('btn-loading');btn.innerHTML=oh;}});}function changeAdminPassword(){  var cur=document.getElementById('changeCurPw').value,nxt=document.getElementById('changeNewPw').value;  if(!cur||!nxt){alert('모두 입력하세요.');return;}  if(nxt.length<8){alert('8자리 이상 입력하세요.');return;}if(new TextEncoder().encode(nxt).length>=64){alert('비밀번호는 UTF-8 기준 64바이트 미만이어야 합니다.');return;}  var btn=document.getElementById('btnChangePw'),oh=btn?btn.innerHTML:'';  if(btn){btn.disabled=true;btn.classList.add('btn-loading');btn.innerHTML='<span class=\"spin\"></span> 변경 중...';}  fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'cur_pw='+encodeURIComponent(cur)+'&new_pw='+encodeURIComponent(nxt)})  .then(function(r){return r.json();})  .then(function(d){    if(d.status==='ok'){alert('변경 완료! 새 비밀번호로 로그인합니다.');rememberAdminPassword(nxt);    document.getElementById('changeCurPw').value='';document.getElementById('changeNewPw').value='';}    else alert('변경 실패: '+(d.message||'현재 비밀번호 확인'));}  ).catch(function(e){alert('통신 오류: '+e);})  .finally(function(){if(btn){btn.disabled=false;btn.classList.remove('btn-loading');btn.innerHTML=oh;}});}function restoreStorageDefaults(){  if(!g_adminPw){var typed=prompt('초기화하려면 현재 관리자 비밀번호를 입력하세요.');if(!typed)return;rememberAdminPassword(typed);}  if(!confirm('SD 파일은 보존합니다. SD의 API 키와 Wi-Fi JSON은 보존하며 첫 화면 및 관리자 비밀번호만 기본값으로 복원됩니다. Wi-Fi 정보와 펌웨어는 유지됩니다. 계속할까요?'))return;  var phrase=prompt('계속하려면 초기화라고 입력하세요.');if(phrase!=='초기화')return;  var btn=document.getElementById('btnRestoreDefaults');if(btn){btn.disabled=true;btn.textContent='초기화 중...';}  fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'cur_pw='+encodeURIComponent(g_adminPw)+'&"
    "restore_defaults=1'})  .then(function(r){return r.json().then(function(d){if(!r.ok||d.status!=='ok')throw new Error(d.message||'초기화에 실패했습니다.');return d;});})  .then(function(){rememberAdminPassword('00000000');fetchFiles(true);updateStats();loadAdminSettings();alert('SD 파일을 보존하고 관리자 기본값을 복원했습니다. 기본 관리자 비밀번호는 00000000입니다.');})  .catch(function(e){alert('초기화 실패: '+uiErrorText(e));})  .finally(function(){if(btn){btn.disabled=false;btn.textContent='관리자 설정 기본값 복원';}});}checkAdminAuth();updateStats();fetchLogs();fetchFiles();setInterval(function(){if(!g_uploading&&!g_collecting)updateStats();},2500);setInterval(function(){if(!g_uploading&&!g_collecting)fetchLogs();},7000);</script></body></html>";
